// Rotate through a fixed list of already-approved clip numbers, posting one
// per tick. Edit PROJECT / RUN / QUEUE for your run, or feed these from a
// Google Sheet (see 05_sheets_log) instead of hardcoding.
const PROJECT = 'Financial 1';
const RUN = 'REPLACE_RUN_NAME';
const QUEUE = [1, 2, 3];
const data = $getWorkflowStaticData('global');
data.dripIndex = (data.dripIndex || 0);
if (data.dripIndex >= QUEUE.length) return [];
const clip = QUEUE[data.dripIndex];
data.dripIndex += 1;
return [{ json: { project: PROJECT, run_name: RUN, clip } }];

